import math
import sys

def archimedean_spiral(b, phi):
    r = b * phi
    return r * math.cos(phi), r * math.sin(phi)

def intersects_spiral(b, phi1, phi2):
    r1 = b * phi1
    r2 = b * phi2
    return r1 * r2 > 0 and abs(phi1 - phi2) < math.pi

def find_detachment_point(b, tx, ty):
    def distance(p1, p2):
        return math.sqrt((p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2)

    def direction_vector(phi):
        r = b * phi
        return -r * math.sin(phi), r * math.cos(phi)

    def projection_length(v1, v2):
        return (v1[0] * v2[0] + v1[1] * v2[1]) / math.sqrt(v2[0] ** 2 + v2[1] ** 2)

    def is_valid_phi(phi):
        px, py = archimedean_spiral(b, phi)
        vx, vy = direction_vector(phi)
        target_vector = (tx - px, ty - py)
        proj_length = projection_length(target_vector, (vx, vy))
        if proj_length <= 0:
            return False
        intersection_phi = phi + proj_length / b
        return not intersects_spiral(b, phi, intersection_phi)

    low, high = 0, 10000
    while high - low > 1e-6:
        mid = (low + high) / 2
        if is_valid_phi(mid):
            high = mid
        else:
            low = mid
    return archimedean_spiral(b, low)

